body.css:
/* Glass's material: everything drawn is made of these names, and nothing
   else. Colours come in a light and a dark; type is a serif to read in and a
   sans for what stands around the reading; the measure keeps a line short
   enough to read. */

:root {
  --ground: #fbfaf7;
  --raised: #ffffff;
  --ink: #23211d;
  --quiet: #6f6a61;
  --line: #e4e0d7;
  --accent: #3d5a80;

  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --text: 18px;
  --leading: 1.6;
  --leading-close: 1.5;
  --leading-tight: 1.2;
  --lead: 1.12em;
  --aside: 0.93em;
  --code: 0.8em;
  --title: 2rem;
  --heading: 1.1rem;
  --small: 0.875rem;
  --smaller: 0.75rem;

  --measure: 40rem;
  --gap: 1rem;
  --inset: 0.8em 1em;
  --radius: 8px;
  --pill: 99px;
  --hairline: 1px;
  --rule: 3px;

  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --ground: #171614;
    --raised: #1e1d1a;
    --ink: #e8e4dc;
    --quiet: #9b958a;
    --line: #2f2c28;
    --accent: #9db4d6;
  }
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink);
  font: var(--text) / var(--leading) var(--serif);
  -webkit-font-smoothing: antialiased;
}

#glass {
  max-width: var(--measure);
  min-height: 100dvh;
  margin: 0 auto;
  padding: 0 var(--gap);
}

a {
  color: var(--accent);
}

code,
pre {
  font-family: var(--mono);
}

.glass-note {
  color: var(--quiet);
  font: var(--small) / var(--leading-close) var(--sans);
}

/* A place: what a mount draws whole. The way down to it stands above its
   title, quiet, in the sans. */

.place > nav {
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  margin-bottom: calc(var(--gap) * 2.5);
}

.place > nav a {
  color: inherit;
  text-decoration: none;
}

.place > nav a:hover {
  color: var(--ink);
}

.place > nav a + a::before {
  content: "›";
  margin: 0 0.5em;
  opacity: 0.6;
}

.place > h1 {
  font-size: var(--title);
  line-height: var(--leading-tight);
  font-weight: 600;
  margin: 0 0 calc(var(--gap) * 1.25);
  letter-spacing: -0.01em;
}

.place > h2 {
  font: var(--small) / var(--leading-close) var(--sans);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--quiet);
  margin: calc(var(--gap) * 2.5) 0 calc(var(--gap) * 0.75);
}

.place pre {
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  padding: var(--inset);
  overflow: auto;
  max-height: 32rem;
  font-size: var(--code);
  line-height: var(--leading-close);
}

/* What is said about a thing beside it, small and quiet. */

.meta {
  display: block;
  font: var(--smaller) / var(--leading-close) var(--sans);
  color: var(--quiet);
}

/* A card: what a face slot draws, entered by a press. The slot is what is
   pressed and focused, so it is the slot that marks the card. */

.card {
  display: block;
  padding: var(--gap) calc(var(--gap) * 1.15);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  background: var(--raised);
  cursor: pointer;
  transition: border-color 0.15s;
}

.slot.face:hover > .card,
.slot.face:focus-visible > .card {
  border-color: var(--quiet);
}

.slot.face:focus-visible {
  outline: none;
}

.card .meta {
  margin-top: 0.5em;
}

/* A list: its items one under another. */

.list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: calc(var(--gap) * 0.75);
}

/* A component made of data: its mounts one under another, set off by
   space. */

.template {
  padding: calc(var(--gap) * 3) 0 calc(var(--gap) * 6);
}

.template > .slot + .slot {
  margin-top: calc(var(--gap) * 2);
}

/* Where a mount is, said above what it gives: quiet, and pressed to be
   changed in place. */

.location {
  display: block;
  width: 100%;
  margin: calc(var(--gap) * 1.5) 0 0;
  padding: 0.5rem 0;
  font: var(--small) / var(--leading-close) var(--sans);
  color: var(--quiet);
  text-align: left;
  background: none;
  border: 0;
  border-bottom: var(--hairline) solid var(--line);
  cursor: text;
}

.location:hover,
.location:focus-visible {
  color: var(--ink);
  outline: none;
}

.location-edit {
  margin: calc(var(--gap) * 1.5) 0 0;
  padding: 0.5rem 0;
  border-bottom: var(--hairline) solid var(--line);
  font: var(--small) / var(--leading-close) var(--sans);
}

.location-ways {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-bottom: 0.5rem;
}

.location-ways button {
  font: inherit;
  color: var(--ink);
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--pill);
  padding: 0.25em 0.8em;
  cursor: pointer;
}

.location-ways button:hover {
  border-color: var(--quiet);
}

.location-input {
  display: block;
  box-sizing: border-box;
  width: 100%;
  padding: 0.45rem 0.6rem;
  font: var(--smaller) / var(--leading-close) var(--mono);
  color: var(--ink);
  background: transparent;
  border: var(--hairline) solid var(--line);
  border-radius: calc(var(--radius) * 0.6);
}

.location-said:empty {
  display: none;
}

.location-said {
  margin: 0.4rem 0 0;
  color: var(--quiet);
  font-size: var(--smaller);
}

/* A mount's menu: what can be done where it was pressed. */

.menu {
  position: fixed;
  z-index: 10;
  min-width: 14rem;
  padding: 0.35rem;
  background: var(--raised);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 0.18);
  font: var(--small) / var(--leading-close) var(--sans);
}

.menu-title {
  padding: 0.4rem 0.6rem 0.3rem;
  color: var(--quiet);
  font-size: var(--smaller);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.menu button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.45rem 0.6rem;
  border: 0;
  border-radius: calc(var(--radius) - 2px);
  background: none;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.menu button:hover,
.menu button:focus-visible {
  background: var(--line);
  outline: none;
}

.menu button[aria-disabled="true"] {
  color: var(--quiet);
  cursor: default;
}

.menu-said {
  padding: 0 0.6rem 0.45rem;
  color: var(--quiet);
  font-size: var(--smaller);
}

.menu-said:empty {
  display: none;
}

.menu-value {
  display: block;
  box-sizing: border-box;
  width: min(28rem, 80vw);
  margin: 0.2rem 0 0.35rem;
  padding: 0.5rem 0.6rem;
  font: var(--smaller) / var(--leading-close) var(--mono);
  color: var(--ink);
  background: transparent;
  border: var(--hairline) solid var(--line);
  border-radius: calc(var(--radius) * 0.6);
  resize: vertical;
}
